'use server';
/**
 * @fileOverview Provides AI-powered cake flavor and design suggestions.
 *
 * - getAICakeSuggestions - A function that suggests personalized cake flavors and designs.
 * - AICakeSuggestionInput - The input type for the getAICakeSuggestions function.
 * - AICakeSuggestionOutput - The return type for the getAICakeSuggestions function.
 */

import { ai } from '@/ai/genkit';
import { z } from 'genkit';

const AICakeSuggestionInputSchema = z.object({
  currentTrends: z.string().describe('A summary of current cake trends, e.g., "floral designs, natural flavors, and minimalist aesthetics."'),
  pastOrderHistory: z
    .array(z.string())
    .describe('A list of cake names or descriptions from the user\'s past orders, e.g., ["Chocolate Fudge Cake", "Red Velvet with Cream Cheese Frosting"].'),
});
export type AICakeSuggestionInput = z.infer<typeof AICakeSuggestionInputSchema>;

const AICakeSuggestionOutputSchema = z.object({
  suggestions: z.array(
    z.object({
      flavor: z.string().describe('The suggested cake flavor, e.g., "Lavender Honey".'),
      design: z.string().describe('A detailed description of the suggested cake design, e.g., "A two-tiered cake with delicate lavender-colored fondant, edible silver leaf accents, and a drizzle of honey ganache."'),
    })
  ).describe('A list of personalized cake suggestions based on trends and past orders.'),
});
export type AICakeSuggestionOutput = z.infer<typeof AICakeSuggestionOutputSchema>;

export async function getAICakeSuggestions(
  input: AICakeSuggestionInput
): Promise<AICakeSuggestionOutput> {
  return aiCakeSuggestionFlow(input);
}

const prompt = ai.definePrompt({
  name: 'aiCakeSuggestionPrompt',
  input: { schema: AICakeSuggestionInputSchema },
  output: { schema: AICakeSuggestionOutputSchema },
  prompt: `You are an expert cake sommelier, specializing in recommending delicious and visually appealing cakes.
Your task is to suggest personalized cake flavors and designs to a customer based on current trends and their past order history.
Aim for creative and unique suggestions.

Current Cake Trends:
{{{currentTrends}}}

Customer's Past Order History:
{{#if pastOrderHistory}}
  {{#each pastOrderHistory}}
  - {{{this}}}
  {{/each}}
{{else}}
  No past order history available.
{{/if}}

Please provide 3-5 distinct cake suggestions. For each suggestion, provide a unique flavor and a detailed design description.
`,
});

const aiCakeSuggestionFlow = ai.defineFlow(
  {
    name: 'aiCakeSuggestionFlow',
    inputSchema: AICakeSuggestionInputSchema,
    outputSchema: AICakeSuggestionOutputSchema,
  },
  async (input) => {
    const { output } = await prompt(input);
    return output!;
  }
);
